I did not add the `last-input` recording. It needs a `state-rw` import (or similar), and the node's `with` clause grants only `http-client`, `notifier` and `wall-clock`. Adding a state import would exceed its authority, so the output and imports are unchanged.

```wit
package gen:node;

world node {
    use aap:caps/types@0.1.0.{heartbeat-report};

    import aap:caps/http-client@0.1.0;
    import aap:caps/notifier@0.1.0;
    import wasi:clocks/wall-clock@0.2.0;

    export run: func(feed-url: string) -> heartbeat-report;
}
```

```rust
wit_bindgen::generate!({
    path: "wit",
    world: "node",
    generate_all,
});

use crate::aap::caps::{http_client, notifier};
use crate::wasi::clocks::wall_clock;

struct Node;

impl Guest for Node {
    fn run(feed_url: String) -> HeartbeatReport {
        let seconds = wall_clock::now().seconds;

        let fetched = match http_client::fetch(&feed_url) {
            Ok(body) => body.chars().count() as u32,
            Err(_) => 0,
        };

        let notified = notifier::notify(&format!(
            "heartbeat at {}s: fetched {} chars from {}",
            seconds, fetched, feed_url
        ));

        // Contract: ensures notified == true. Never emit a violating output.
        if !notified {
            panic!("notification was not accepted");
        }

        HeartbeatReport {
            seconds,
            fetched,
            notified,
        }
    }
}

export!(Node);
```

